"""Evaluate locked Make rules; do not invent a System SDK allowlist."""
import hashlib,json,pathlib,subprocess,struct,re
R=pathlib.Path('/runtime-build');A=R/'aosp';O=A/'out-sdk35/soong/system-sdk-origin';O.mkdir(parents=True,exist_ok=True)
lock=json.loads((R/'contract/coherent-source-lock.json').read_text());pin=next(p for p in lock['projects'] if p['path']=='build/make');repo=A/'build/make';inputs={}
for name in ['core/version_util.mk','common/math.mk','core/build_id.mk','core/soong_config.mk']:
 path=repo/name;data=path.read_bytes();original=subprocess.check_output(['git','-c','safe.directory='+str(repo),'-C',str(repo),'show',pin['revision']+':'+name]);assert original==data,'Original Make input drift: '+name;inputs['build/make/'+name]=hashlib.sha256(data).hexdigest()
release=A/'out-sdk35/release-config/release_config-sdk35_native_host-ap4a.varmk';inputs[str(release.relative_to(A))]=hashlib.sha256(release.read_bytes()).hexdigest()
mk=O/'derive.mk';mk.write_text("empty :=\nspace := $(empty) $(empty)\ncomma := ,\nBUILD_SYSTEM := build/make/core\ninclude "+str(release.relative_to(A))+"\ninclude build/make/common/math.mk\ninclude build/make/core/version_util.mk\n.PHONY: print-system-sdk\nprint-system-sdk:\n\t@printf '%s\\n' '$(PLATFORM_SYSTEMSDK_VERSIONS)' '$(BUILD_ID)' '$(PLATFORM_SDK_EXTENSION_VERSION)' '$(PLATFORM_BASE_SDK_EXTENSION_VERSION)'\n")
tool=A/'prebuilts/build-tools/linux_musl-arm64/bin/ckati';data=tool.read_bytes();assert data[:4]==b'\x7fELF' and struct.unpack('<H',data[18:20])[0]==183;parent=A/'prebuilts/build-tools';original=subprocess.check_output(['git','-c','safe.directory='+str(parent),'-C',str(parent),'show','770c104a7909083b8b54d02e6d55351fe1351d5d:linux_musl-arm64/bin/ckati']);assert original==data;inputs[str(tool.relative_to(A))]=hashlib.sha256(data).hexdigest()
q=subprocess.run([str(tool),'-f',str(mk),'print-system-sdk'],cwd=A,capture_output=True,text=True,check=True);output=q.stdout.strip().splitlines();assert len(output)==4;versions=output[0].split();build_id=output[1];assert re.fullmatch(r'[A-Za-z0-9_.-]+',build_id),'Invalid original BuildId';assert versions and all(v.isdecimal() for v in versions),'Invalid original System SDK output: '+repr(q.stdout)
assert output[2].isdecimal() and output[3].isdecimal()
report={'Platform_systemsdk_versions':versions,'BuildId':build_id,'Platform_sdk_extension_version':int(output[2]),'Platform_base_sdk_extension_version':int(output[3]),'source_project_revision':pin['revision'],'inputs_sha256':inputs,'make_stderr':q.stderr,'sdk_version_changed':False};(O/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
